def olcut(bulunan, altin):
    kesisim = bulunan & altin
    kesinlik = len(kesisim) / len(bulunan)
    anma = len(kesisim) / len(altin)
    f1 = 2 * kesinlik * anma / (kesinlik + anma)
    return round(kesinlik, 4), round(anma, 4), round(f1, 4)

