def normalize(s):
    s = s.lower()
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append(" ")
    return " ".join("".join(out).split())


def anahtar(kayit):
    return (normalize(kayit["baslik"]), kayit["yil"])


