def h_indeksi(atiflar):
    s = sorted(atiflar, reverse=True)
    h = 0
    for i, v in enumerate(s, start=1):
        if v >= i:
            h = i
    return h


def i10(atiflar):
    return sum(1 for a in atiflar if a >= 10)


